#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Install and run ROM 9.0.12i4d residual legacy refs audit."""
from __future__ import annotations
import base64
import py_compile
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

PATCH_ID="9.0.12i4d"
TARGET_NAME="audit_residual_legacy_refs.py"
TOOL_SOURCE=base64.b64decode("").decode("utf-8")


def fail(message):
    print(f"❌ {message}")
    raise SystemExit(1)


def find_root():
    here=Path(__file__).resolve()
    for root in (here.parent.parent,Path.cwd(),Path.cwd().parent):
        root=root.resolve()
        if (root/"db.py").is_file() and (root/"tools"/"db_cleanup_readiness.py").is_file():
            return root
    fail("Не знайдено корінь ROM.")


def main():
    root=find_root()
    target=root/"tools"/TARGET_NAME
    backup=None
    if target.exists() and target.read_text(encoding="utf-8-sig")!=TOOL_SOURCE:
        backup_dir=root/"backup"; backup_dir.mkdir(parents=True,exist_ok=True)
        stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
        backup=backup_dir/f"tools_{TARGET_NAME}_{PATCH_ID}_{stamp}.bak"
        shutil.copy2(target,backup)
    target.write_text(TOOL_SOURCE,encoding="utf-8")
    try:
        py_compile.compile(str(target),doraise=True)
        result=subprocess.run([sys.executable,str(target)],cwd=root)
        if result.returncode!=0:
            raise RuntimeError(f"audit exit code {result.returncode}")
    except Exception as exc:
        if backup is not None: shutil.copy2(backup,target)
        elif target.exists(): target.unlink()
        fail(f"Аудит не пройдено; встановлення відкочено: {exc}")
    print(f"✅ Патч {PATCH_ID} успішно застосовано.")
    print(f"✅ Створено: tools/{TARGET_NAME}")
    print("✅ Створено: DB_CLEANUP_9_0_12I4D_RESIDUAL_LEGACY_REFS_AUDIT.md")
    print("✅ Gameplay-код, readiness tool і база даних не змінені.")
    print("Резервні копії:")
    print(f"   {backup.relative_to(root) if backup else 'не потрібні - новий файл'}")
    print("Перевірки:")
    print(f"   python ./tools/{TARGET_NAME}")
    print("   python ./tools/db_cleanup_readiness.py")


if __name__=="__main__":
    main()
